from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    base = counts.most_common(1)[0][0]
    line_color = max((v for v in counts if v != base), key=lambda v: counts[v])
    special = {v for v in counts if v not in (base, line_color)}

    rows = [r for r in range(h) if base not in grid[r]]
    cols = [c for c in range(w) if all(grid[r][c] != base for r in range(h))]

    def active_row(r):
        return any(grid[r][c] in special for c in cols)

    def active_col(c):
        return any(grid[r][c] in special for r in rows)

    while rows and not active_row(rows[0]):
        rows.pop(0)
    while rows and not active_row(rows[-1]):
        rows.pop()
    while cols and not active_col(cols[0]):
        cols.pop(0)
    while cols and not active_col(cols[-1]):
        cols.pop()

    out = []
    for r0, r1 in zip(rows, rows[1:]):
        line = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            color = corners[0]
            if color in special and all(v == color for v in corners):
                line.append(color)
            else:
                line.append(base)
        out.append(line)
    return out

